import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create plane geometry (default 1x1)
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Create material with texture
  const material = new MeshBasicNodeMaterial();
  material.colorNode = uv().convert('vec3');

  // Load and apply texture
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);
  texturePromise.then((texture) => {
    material.map = texture;
    material.needsUpdate = true;
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene position
  if (config.scenePosition) {
    mesh.position.set(
      config.scenePosition[0],
      config.scenePosition[1],
      config.scenePosition[2]
    );
  }

  // Apply rotation
  if (config.sceneRotation) {
    mesh.rotation.set(
      config.sceneRotation[0],
      config.sceneRotation[1],
      config.sceneRotation[2]
    );
  }

  // Apply scale
  if (config.sceneScale) {
    mesh.scale.set(
      config.sceneScale[0],
      config.sceneScale[1],
      config.sceneScale[2]
    );
  }

  // Initialize userData
  mesh.userData.handlers = {};
  mesh.userData.cleanup = function() {
    geometry.dispose();
    material.dispose();
    if (material.map) {
      material.map.dispose();
    }
  };

  return mesh;
}
